            header=value['append']
            if set(header)!={'header','append_action'} or header['append_action']!='OVERWRITE_IF_EXISTS_OR_ADD':raise ValueError('explicit overwrite semantics required')
            if set(header['header'])!={'key','value'} or not header['header']['key'].startswith('x-'):raise ValueError('ordinary extension response header required')
            headers.append(copy.deepcopy(header))
